            val s = p.shape ?: return null
            fun kindOf(prio: Int): WayKind? = if (bike) when (CueRule.bikeKind(prio)) {
                1 -> WayKind.TRACK; 3 -> WayKind.ROAD; else -> null
            } else when (CueRule.hikeClass(prio)) {
                1 -> WayKind.PATH; 2 -> WayKind.TRACK; in 18..Int.MAX_VALUE -> WayKind.ROAD; else -> null
            }
            val out = kindOf(s.outPrio)
            return out?.takeIf { it != kindOf(s.inPrio) }
        }
